const staticData = $getWorkflowStaticData('global');
staticData.seenMessageIds = staticData.seenMessageIds || {};
staticData.knownPhones = staticData.knownPhones || {};

const body = $input.first().json.body;
const entry = body?.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];

// Meta tambien envia status callbacks (delivered/read). No hay nada que procesar.
if (!message) {
  return [];
}

const messageId = message.id;

// Meta reintenta la entrega del webhook si no responde rapido. Evita procesar el mismo mensaje dos veces.
if (staticData.seenMessageIds[messageId]) {
  return [];
}
staticData.seenMessageIds[messageId] = Date.now();
const seenIds = Object.keys(staticData.seenMessageIds);
if (seenIds.length > 500) {
  seenIds.sort((a, b) => staticData.seenMessageIds[a] - staticData.seenMessageIds[b]);
  for (const id of seenIds.slice(0, seenIds.length - 500)) {
    delete staticData.seenMessageIds[id];
  }
}

const from = message.from;
const telefonoValido = /^\d{8,15}$/.test(from || '');

const messageType = message.type;
let texto = '';
let imagenId = null;
let route = 'unsupported';

if (messageType === 'text') {
  texto = (message.text?.body || '').trim();
  route = texto.length > 0 ? 'process' : 'unsupported';
} else if (messageType === 'image') {
  texto = (message.image?.caption || '').trim();
  imagenId = message.image?.id || null;
  route = 'process';
} else if (messageType === 'audio' || messageType === 'voice') {
  route = 'audio';
} else {
  // video, document, sticker, location, contacts, etc. No estan soportados todavia.
  route = 'unsupported';
}

const esPrimerContacto = !staticData.knownPhones[from];
staticData.knownPhones[from] = true;

return [{
  json: {
    cliente_numero: from,
    telefono_valido: telefonoValido,
    tipo_mensaje: messageType,
    texto,
    imagen_id: imagenId,
    phone_number_id: value?.metadata?.phone_number_id,
    timestamp: message.timestamp,
    message_id: messageId,
    route,
    es_primer_contacto: esPrimerContacto
  }
}];

const SUPABASE_PROJECT_URL = 'prixpldbhstzeovfjwxt.supabase.co';
const base = $('Code - Parse Incoming Message').item.json;
const publicUrl = `https://${SUPABASE_PROJECT_URL}/storage/v1/object/public/deliver-ai-images/orders/${base.cliente_numero}/${base.imagen_id}.jpg`;

return [{
  json: {
    reference_image_url: publicUrl
  }
}];

const base = $('Code - Parse Incoming Message').item.json;
const imageUrl = $json.reference_image_url || '';

let mensajeCliente = base.texto;
if (base.tipo_mensaje === 'image') {
  const caption = base.texto ? ` El cliente escribio junto a la foto: "${base.texto}".` : ' El cliente no escribio texto adicional.';
  mensajeCliente = `[El cliente envio una foto de referencia para el pastel.]${caption}`;
}

const fechaHoy = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Bogota' }).format(new Date());
const contexto = `[Datos ya conocidos por el sistema - no los preguntes: phone_number="${base.cliente_numero}"; reference_image="${imageUrl}"; fecha_actual="${fechaHoy}"]`;

return [{
  json: {
    chatInput: `${contexto}\nMensaje del cliente: ${mensajeCliente}`,
    sessionId: base.cliente_numero
  }
}];

let data = $json.output;
if (typeof data === 'string') {
  try {
    data = JSON.parse(data);
  } catch (e) {
    return [{
      json: {
        parse_error: true,
        order_complete: false,
        customer_confirmed: false,
        customer_message: 'Perdona, tuve un problema entendiendo tu mensaje. Puedes escribirlo de nuevo, por favor?'
      }
    }];
  }
}

const phone = $('Code - Construir Input del Agente').item.json.sessionId;

const requiredFields = ['customer_name', 'cake_flavor', 'filling', 'servings', 'decoration', 'delivery_date'];
const missing = [];
for (const field of requiredFields) {
  const value = data[field];
  if (value === null || value === undefined || value === '') {
    missing.push(field);
  }
}

let servingsValid = true;
if (data.servings !== null && data.servings !== undefined && data.servings !== '') {
  const n = Number(data.servings);
  if (!Number.isInteger(n) || n <= 0) {
    servingsValid = false;
    missing.push('servings (numero invalido)');
  }
}

let dateValid = true;
if (data.delivery_date) {
  const deliveryDate = new Date(data.delivery_date);
  const minLead = new Date(Date.now() + 48 * 60 * 60 * 1000);
  if (isNaN(deliveryDate.getTime()) || deliveryDate < minLead) {
    dateValid = false;
    missing.push('delivery_date (fecha invalida o con menos de 48h de anticipacion)');
  }
}

const serverComplete = missing.length === 0 && servingsValid && dateValid;
const orderComplete = Boolean(data.order_complete) && serverComplete;
const customerConfirmed = Boolean(data.customer_confirmed) && orderComplete;

return [{
  json: {
    ...data,
    phone_number: phone,
    order_complete: orderComplete,
    customer_confirmed: customerConfirmed,
    missing_fields: missing,
    parse_error: false
  }
}];

const d = $json;

return [{
  json: {
    ...d,
    backendBody: {
      subTotal: 0,
      customerName: d.customer_name,
      phoneNumber: Number(d.phone_number),
      deliveryDate: d.delivery_date,
      deliveryAddress: d.delivery_address || '',
      notes: d.notes || '',
      orderItems: [
        {
          quantity: 1,
          flavor: d.cake_flavor,
          filling: d.filling,
          servings: Number(d.servings) || 1,
          decoration: d.decoration,
          referenceImageUrl: d.reference_image || ''
        }
      ]
    }
  }
}];

const orderData = $('Code - Construir Body del Pedido para Backend').item.json;
const backendOrderId = $json.id;

return [{
  json: {
    phone_number: orderData.phone_number,
    final_message: `${orderData.customer_message}\n\nNumero de pedido: #${backendOrderId}`
  }
}];

const orderData = $('Code - Construir Body del Pedido para Backend').item.json;

return [{
  json: {
    phone_number: orderData.phone_number,
    final_message: 'Se nos presento un problema tecnico registrando tu pedido. Ya notificamos a nuestro equipo y te contactaremos en breve. Gracias por tu paciencia!'
  }
}];
